MW.installNavigation=function(Game){const P=Game.prototype;
P.stopAuto=function(message){if(!this.auto)return;this.auto=null;this.moving=false;this.keys.clear();this.resetStick?.();if(message)this.notify(message);this.navigationUI();};
P.toggleAuto=function(){if(this.auto){this.stopAuto('자동 진행을 멈췄습니다.');return;}if(dialog.open||this.paused)return;if(!this.step()&&!this.dungeon&&!this.tower){this.notify('현재 지역의 의뢰를 모두 완료했습니다.');return;}this.keys.clear();this.resetStick?.();this.auto={step:this.q().step,region:this.p.region,world:this.world,target:null,path:[],repath:0,stall:0,lastX:this.p.x,lastY:this.p.y,skip:new Set()};this.tracking=true;this.notify('자동 진행 시작 · 퀘스트 창을 다시 누르거나 직접 조작하면 멈춥니다.');this.navigationUI();};
P.navigationUI=function(){const box=$('.quest-hud');box.setAttribute?.('aria-pressed',String(!!this.auto));box.classList.toggle?.('auto-active',!!this.auto);$('#autostatus').textContent=this.auto?'자동 진행 중 · 눌러서 중지':'눌러서 자동 진행';$('#track').textContent=this.auto?'Ⅱ':'▶';};
P.routeTo=function(target,reach=65){const w=this.world,size=48,key=(x,y)=>y*w.w+x,clear=(a,b)=>{const n=Math.ceil(Math.hypot(a.x-b.x,a.y-b.y)/8);for(let i=1;i<=n;i++)if(w.solid(a.x+(b.x-a.x)*i/n,a.y+(b.y-a.y)*i/n))return false;return true;};if(this.navWorld!==w){this.navWorld=w;this.navLinks=new Map();}const point=k=>({x:(k%w.w)*size,y:Math.floor(k/w.w)*size});let start=null,best=Infinity;const cx=Math.round(this.p.x/size),cy=Math.round(this.p.y/size);for(let y=cy-2;y<=cy+2;y++)for(let x=cx-2;x<=cx+2;x++){const p={x:x*size,y:y*size},d=Math.hypot(p.x-this.p.x,p.y-this.p.y);if(x>=2&&y>=2&&x<w.w-2&&y<w.h-2&&d<best&&!w.solid(p.x,p.y)&&clear(this.p,p)){start=key(x,y);best=d;}}if(start===null)return null;const queue=[start],parents=new Map([[start,null]]);let end=null;for(let i=0;i<queue.length;i++){const k=queue[i],p=point(k);if(Math.hypot(p.x-target.x,p.y-target.y)<=reach&&clear(p,target)){end=k;break;}let neighbors=this.navLinks.get(k);if(!neighbors){neighbors=[];for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const x=p.x/size+dx,y=p.y/size+dy,n=key(x,y),next=point(n);if(x>=2&&y>=2&&x<w.w-2&&y<w.h-2&&!w.solid(next.x,next.y)&&clear(p,next))neighbors.push(n);}this.navLinks.set(k,neighbors);}for(const n of neighbors)if(!parents.has(n)){parents.set(n,k);queue.push(n);}}if(end===null)return null;const path=[];for(let k=end;k!==null;k=parents.get(k))path.push(point(k));return path.reverse();};
P.autoGoal=function(){const nearest=list=>list.filter(o=>!this.auto.skip.has(o)).sort((a,b)=>Math.hypot(a.x-this.p.x,a.y-this.p.y)-Math.hypot(b.x-this.p.x,b.y-this.p.y));if(this.tower)return nearest(this.enemies.filter(e=>e.tower&&!e.dead)).map(target=>({target,fight:true}));if(this.dungeon){const enemies=nearest(this.enemies.filter(e=>!e.dead));if(enemies.length)return enemies.map(target=>({target,fight:true}));return nearest(this.world.objects.filter(o=>o.type==='landmark'&&!this.dungeon.seals.includes(o.id))).map(target=>({target}));}const kind=this.step()?.kind;if(kind==='kill'||kind==='boss'||(kind==='defend'&&this.event)){return nearest(this.enemies.filter(e=>!e.dead&&(kind==='kill'?!e.boss:kind==='boss'?e.boss:e.event))).map(target=>({target,fight:true}));}if(kind==='escort'&&this.escort){const threats=nearest(this.enemies.filter(e=>!e.dead&&Math.hypot(e.x-this.escort.x,e.y-this.escort.y)<220));if(threats.length)return threats.map(target=>({target,fight:true}));return [{target:{x:11*48,y:28*48},escort:true}];}if(kind==='scout')return nearest(this.world.objects.filter(o=>o.type==='landmark'&&[0,1,3].includes(o.index)&&!this.q().seen.includes(o.id))).map(target=>({target}));if(kind==='collect')return nearest(this.world.objects.filter(o=>o.type==='memory'&&!this.collected.has(o.id))).map(target=>({target}));const target=this.target();return target?[{target}]:[];};
P.updateAuto=function(dt){const a=this.auto;if(!a)return;if(a.world!==this.world||a.region!==this.p.region||(!this.dungeon&&!this.tower&&a.step!==this.q().step)){this.stopAuto('현재 의뢰를 완료했습니다. 다음 의뢰를 눌러 진행하세요.');return;}this.lastInput=this.time;if(this.p.hp<this.stats().hp*.4&&this.p.bag.potion)this.use('potion');if(this.p.hp<this.stats().hp*.2&&!this.p.bag.potion){this.stopAuto('체력이 부족해 자동 진행을 중지했습니다.');return;}const weapon=MW.items.find(i=>i.id===this.p.equip.weapon),reach=weapon?.kind==='bow'?220:weapon?.kind==='staff'?190:75;a.repath-=dt;if(a.repath<=0||!a.goal||a.goal.target.dead){a.repath=.8;const goals=this.autoGoal();let chosen=null;for(const goal of goals){const path=this.routeTo(goal.target,goal.fight?reach-10:70);if(path){chosen={...goal,path};break;}a.skip.add(goal.target);}if(!chosen){a.goal=null;this.moving=false;if(goals.length&&a.skip.size){this.stopAuto('목표로 가는 길을 찾지 못했습니다. 다른 위치에서 다시 시작하세요.');}return;}a.goal=chosen;a.path=chosen.path;}const g=a.goal,t=g.target,d=Math.hypot(t.x-this.p.x,t.y-this.p.y);if(g.fight&&d<reach){this.face=Math.abs(t.x-this.p.x)>Math.abs(t.y-this.p.y)?(t.x>this.p.x?1:3):(t.y>this.p.y?0:2);if(this.cool.attack<=0){if(this.cool.skill<=0&&this.p.mp>=25)this.attack(true);else this.attack();}this.moving=false;return;}if(!g.fight&&!g.escort&&d<85){a.repath=0;if(this.dungeon)this.dungeonInteract();else if(this.world.npcs.includes(t)){this.stopAuto('목표에 도착했습니다. 대화를 확인하세요.');this.npc(t);}else if(t.type==='landmark'){if(['puzzle','escort'].includes(this.step()?.kind))this.stopAuto('목표에 도착했습니다. 대화를 확인하세요.');this.landmark(t);}else this.interact();return;}if(g.escort&&Math.hypot(this.p.x-this.escort.x,this.p.y-this.escort.y)>180){this.moving=false;return;}while(a.path.length&&Math.hypot(a.path[0].x-this.p.x,a.path[0].y-this.p.y)<.001){this.p.x=a.path[0].x;this.p.y=a.path[0].y;a.path.shift();}const next=a.path[0]||(g.fight?t:null);if(!next){this.moving=false;a.repath=0;return;}const dx=next.x-this.p.x,dy=next.y-this.p.y,n=Math.hypot(dx,dy),distance=Math.min(n,190*dt);this.move(this.p,dx/n*distance,dy/n*distance);this.face=Math.abs(dx)>Math.abs(dy)?(dx>0?1:3):(dy>0?0:2);this.moving=true;if(Math.hypot(this.p.x-a.lastX,this.p.y-a.lastY)<.1)a.stall+=dt;else a.stall=0;a.lastX=this.p.x;a.lastY=this.p.y;if(a.stall>1.5){this.stopAuto('이동이 막혀 자동 진행을 멈췄습니다.');}};
P.bindNavigation=function(){const box=$('.quest-hud');box.onclick=()=>this.toggleAuto();box.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();e.stopPropagation();this.toggleAuto();}});$('#minimap-open').onclick=()=>this.regionMap();$('#region-close').onclick=()=>$('#regionmap').close();$('#region-world').onclick=()=>{$('#regionmap').close();this.worldMap();};$('#regionmap').addEventListener('close',()=>{this.paused=this.mapWasPaused||false;$('#minimap-open').focus?.();});window.addEventListener('resize',()=>{if($('#regionmap').open)this.drawRegionMap();});};
P.regionMap=function(){this.stopAuto();this.keys.clear();this.resetStick?.();this.mapWasPaused=this.paused;this.paused=true;$('#region-title').textContent=this.dungeon?MW.regions[this.p.region].name+' · 미궁 '+this.dungeon.floor+'층':this.tower?'시련의 탑 '+this.tower.floor+'층':MW.regions[this.p.region].name;$('#regionmap').showModal();this.drawRegionMap();};
P.drawRegionMap=function(){const canvas=$('#region-canvas'),bounds=canvas.getBoundingClientRect?.()||{width:960,height:600};canvas.width=Math.max(1,Math.round(bounds.width));canvas.height=Math.max(1,Math.round(bounds.height));const c=canvas.getContext('2d'),w=this.world,scale=Math.min((canvas.width-30)/(w.w*48),(canvas.height-30)/(w.h*48)),ox=(canvas.width-w.w*48*scale)/2,oy=(canvas.height-w.h*48*scale)/2,pt=o=>[ox+o.x*scale,oy+o.y*scale];c.clearRect(0,0,canvas.width,canvas.height);c.imageSmoothingEnabled=false;c.drawImage(this.renderer.floor,ox,oy,w.w*48*scale,w.h*48*scale);const paint=Object.create(this.renderer);paint.ctx=c;c.save();c.translate(ox,oy);c.scale(scale,scale);for(const b of w.homes)paint.house(b);for(const o of w.decor)paint.tree(o);c.restore();const dot=(o,col,r)=>{const [x,y]=pt(o);c.fillStyle=col;c.strokeStyle='#10242d';c.lineWidth=1.5;c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fill();c.stroke();};for(const e of this.enemies)if(!e.dead)dot(e,e.boss?'#e38b91':'#bd776e',e.boss?5:3);for(const n of w.npcs)dot(n,'#eee0ae',4);for(const o of w.objects){if(o.type==='memory'&&this.collected.has(o.id))continue;if(o.type==='landmark'||o.type==='portal'||o.type==='memory'){dot(o,o.type==='portal'?'#ba9fd5':o.type==='memory'?'#82c4b8':'#c0c8ad',3);if(o.type==='landmark'&&canvas.width>600){const [x,y]=pt(o);c.font='11px system-ui';c.textAlign='center';c.fillStyle='#10242d';c.fillText(o.name,x+1,y-7);c.fillStyle='#fff3d1';c.fillText(o.name,x,y-8);}}}const target=this.target();if(target){const [x,y]=pt(target);c.fillStyle='#ffd47e';c.strokeStyle='#172b34';c.lineWidth=2;c.beginPath();c.moveTo(x,y-8);c.lineTo(x+7,y);c.lineTo(x,y+8);c.lineTo(x-7,y);c.closePath();c.fill();c.stroke();}dot(this.p,'#d6ffff',6);};
};
